        cg3::Point2d p1 = triangle[i];
        cg3::Point2d p2 = triangle[(i + 1) % 3];
        cg3::Point2d p3 = triangle[(i + 2) % 3];
        double distance = std::sqrt(std::pow(p2.x() - p1.x(), 2) + std::pow(p2.y() - p1.y(), 2));
